using System.Text.Json; namespace GodTreeXOwais.Infrastructure; public sealed record AppSettings(string DefaultAgent="local-planner",bool AutoCheckpoint=true,bool ConfirmDangerousTools=true); public sealed class SettingsStore{readonly string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"GodTreeXOwais","config","settings.json");public AppSettings Load(){try{return JsonSerializer.Deserialize<AppSettings>(File.ReadAllText(path))??new();}catch{return new();}}public void Save(AppSettings s){Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllText(path,JsonSerializer.Serialize(s,new JsonSerializerOptions{WriteIndented=true}));}}